 boolean internet(){try{if(cm==null)return false;NetworkInfo ai=cm.getActiveNetworkInfo();if(ai!=null&&ai.isConnected())return true;Network active=cm.getActiveNetwork();if(active!=null){NetworkCapabilities c=cm.getNetworkCapabilities(active);if(c!=null&&(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||c.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)||c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)))return true;}Network[] all=cm.getAllNetworks();if(all!=null)for(Network n:all){NetworkInfo ni=cm.getNetworkInfo(n);if(ni!=null&&ni.isConnected())return true;NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c!=null&&(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||c.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)||c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)))return true;}WifiManager wm=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wm!=null&&wm.isWifiEnabled()){WifiInfo wi=wm.getConnectionInfo();if(wi!=null&&wi.getNetworkId()!=-1&&wi.getSupplicantState()==SupplicantState.COMPLETED)return true;}}catch(Exception e){}return false;}
